package com.mohymods.kingdomsmp.equipment;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.tags.BlockTags;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.saveddata.SavedData;
import java.util.*;
/** Equipment-only exact successful TreeGrower writes. No quest evidence or retrospective leaf inference. */
public final class MasterGrownTrees extends SavedData {
 private record Cell(String dimension,long pos){ }
 private record Tree(UUID id,String dimension,BlockPos root,String sapling,Map<Long,String> logs){ }
 public static final class Batch {final ServerLevel level;final BlockPos root;final String sapling;final Map<Long,String> logs=new HashMap<>();int leaves;boolean overflow;Batch(ServerLevel l,BlockPos p,BlockState sapling){level=l;root=p.immutable();this.sapling=BuiltInRegistries.ITEM.getKey(sapling.getBlock().asItem()).toString();}}
 private record Pending(Tree tree,int ready){ }
 private static final String NAME="kingdomsmp_master_grown_trees_v1";
 private static final Map<MinecraftServer,MasterGrownTrees> CACHE=new WeakHashMap<>();
 private static final Map<MinecraftServer,ArrayDeque<Pending>> PENDING=new WeakHashMap<>();
 private static final ThreadLocal<ArrayDeque<Batch>> ACTIVE=new ThreadLocal<>();
 private final Map<UUID,Tree> trees=new HashMap<>();private final Map<Cell,UUID> index=new HashMap<>();
 public static void initialize(MinecraftServer server){CACHE.remove(server);PENDING.remove(server);try{var path=server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data/"+NAME+".dat");var data=server.overworld().getDataStorage().computeIfAbsent(new Factory<>(()->{if(java.nio.file.Files.exists(path))throw new IllegalStateException("Existing grown-tree proof failed to load");return new MasterGrownTrees();},MasterGrownTrees::load),NAME);CACHE.put(server,data);}catch(RuntimeException failure){com.mojang.logging.LogUtils.getLogger().error("Master grown-tree evidence unavailable; native growth continues without equipment provenance",failure);}}
 public static Batch begin(ServerLevel level,BlockPos origin,BlockState sapling){if(!level.getServer().isSameThread()||!Set.of("minecraft","aether","twilightforest","ars_nouveau").contains(BuiltInRegistries.BLOCK.getKey(sapling.getBlock()).getNamespace()))return null;var b=new Batch(level,origin,sapling);var stack=ACTIVE.get();if(stack==null){stack=new ArrayDeque<>();ACTIVE.set(stack);}stack.push(b);return b;}
 public static void finish(Batch b,boolean success){if(b==null)return;try{if(success&&!b.overflow&&b.leaves>0&&!b.logs.isEmpty()){var q=PENDING.computeIfAbsent(b.level.getServer(),s->new ArrayDeque<>());if(q.size()<128)q.add(new Pending(new Tree(UUID.randomUUID(),b.level.dimension().location().toString(),b.root,b.sapling,Map.copyOf(b.logs)),b.level.getServer().getTickCount()+2));}}finally{ACTIVE.get().pop();if(ACTIVE.get().isEmpty())ACTIVE.remove();}}
 public static void changed(ServerLevel level,BlockPos pos,BlockState before,BlockState after){try{if(!level.getServer().isSameThread()||before.equals(after))return;var data=CACHE.get(level.getServer());if(data!=null){var key=new Cell(level.dimension().location().toString(),pos.asLong());var id=data.index.remove(key);var tree=data.trees.get(id);if(tree!=null){var logs=new HashMap<>(tree.logs());logs.remove(pos.asLong());if(logs.isEmpty())data.trees.remove(id);else data.trees.put(id,new Tree(id,tree.dimension(),tree.root(),tree.sapling(),Map.copyOf(logs)));data.setDirty();}}
   var stack=ACTIVE.get();if(stack==null||stack.isEmpty())return;var b=stack.peek();if(b.level!=level)return;if(after.is(BlockTags.LEAVES))b.leaves++;if(after.is(BlockTags.LOGS)&&!before.is(BlockTags.LOGS)&&Set.of("minecraft","aether","twilightforest","ars_nouveau").contains(BuiltInRegistries.BLOCK.getKey(after.getBlock()).getNamespace())){if(b.logs.size()>=2048)b.overflow=true;else b.logs.put(pos.asLong(),after.toString());}
  }catch(RuntimeException ignored){}}
 public static void drain(MinecraftServer server){var q=PENDING.get(server);var data=CACHE.get(server);if(q==null||data==null)return;while(!q.isEmpty()&&q.peek().ready()<=server.getTickCount()){var tree=q.removeFirst().tree();var level=server.getLevel(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.DIMENSION,net.minecraft.resources.ResourceLocation.parse(tree.dimension())));if(level==null||data.trees.size()>=8192||data.index.size()+tree.logs().size()>65536)continue;boolean valid=true;for(var e:tree.logs().entrySet()){var at=BlockPos.of(e.getKey());if(!level.hasChunkAt(at)||!level.getBlockState(at).toString().equals(e.getValue())||data.index.containsKey(new Cell(tree.dimension(),e.getKey()))){valid=false;break;}}if(!valid)continue;data.trees.put(tree.id(),tree);tree.logs().keySet().forEach(pos->data.index.put(new Cell(tree.dimension(),pos),tree.id()));data.setDirty();}}
 public static Optional<com.mohymods.kingdomsmp.profession.TreeEvidence.Footprint> footprint(ServerLevel level,BlockPos pos){var data=CACHE.get(level.getServer());if(data==null)return Optional.empty();var tree=data.trees.get(data.index.get(new Cell(level.dimension().location().toString(),pos.asLong())));if(tree==null)return Optional.empty();for(var e:tree.logs().entrySet())if(!level.hasChunkAt(BlockPos.of(e.getKey()))||!level.getBlockState(BlockPos.of(e.getKey())).toString().equals(e.getValue()))return Optional.empty();return Optional.of(new com.mohymods.kingdomsmp.profession.TreeEvidence.Footprint(tree.root(),tree.logs().keySet().stream().map(BlockPos::of).toList(),tree.sapling()));}
 @Override public CompoundTag save(CompoundTag root,HolderLookup.Provider registries){root.putInt("schema",1);var rows=new ListTag();for(var tree:trees.values()){var row=new CompoundTag();row.putUUID("id",tree.id());row.putString("dimension",tree.dimension());row.putLong("root",tree.root().asLong());row.putString("sapling",tree.sapling());var logs=new ListTag();tree.logs().forEach((pos,state)->{var cell=new CompoundTag();cell.putLong("pos",pos);cell.putString("state",state);logs.add(cell);});row.put("logs",logs);rows.add(row);}root.put("trees",rows);return root;}
 private static MasterGrownTrees load(CompoundTag root,HolderLookup.Provider registries){if(root.getInt("schema")!=1||!root.getAllKeys().equals(Set.of("schema","trees")))throw new IllegalArgumentException("Invalid Master tree schema");var rows=root.getList("trees",Tag.TAG_COMPOUND);if(rows.size()>8192)throw new IllegalArgumentException("Excess tree evidence");var data=new MasterGrownTrees();for(var value:rows){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("id","dimension","root","sapling","logs"))||!row.hasUUID("id"))throw new IllegalArgumentException("Invalid tree row");String dim=row.getString("dimension"),sapling=row.getString("sapling");net.minecraft.resources.ResourceLocation.parse(dim);net.minecraft.resources.ResourceLocation.parse(sapling);var logs=new HashMap<Long,String>();var encoded=row.getList("logs",Tag.TAG_COMPOUND);if(encoded.isEmpty()||encoded.size()>2048)throw new IllegalArgumentException("Invalid tree footprint");UUID id=row.getUUID("id");for(var item:encoded){var c=(CompoundTag)item;if(!c.getAllKeys().equals(Set.of("pos","state"))||c.getString("state").length()>256||c.getString("state").isBlank()||logs.put(c.getLong("pos"),c.getString("state"))!=null||data.index.put(new Cell(dim,c.getLong("pos")),id)!=null||data.index.size()>65536)throw new IllegalArgumentException("Invalid repeated tree cell");}if(data.trees.put(id,new Tree(id,dim,BlockPos.of(row.getLong("root")),sapling,Map.copyOf(logs)))!=null)throw new IllegalArgumentException("Duplicate tree");}return data;}
}
